import {guardHenConstruction} from './hen-rig-transaction.js';
import * as T from './vendor/three.module.js';
import {createHenLadderMotion} from './hen-ladder-motion.js';
import {LADDER_PRESETS} from './ladder-motion.js';
import {WOODEN_LADDER,IRON_LADDER_EXIT} from './tower-geometry.js';
import {toWorld} from './hybrid-world.js';
const V=a=>new T.Vector3(...a),ease=t=>{t=T.MathUtils.clamp(t,0,1);return t*t*(3-2*t);},yawQ=y=>new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),-y*Math.PI/180),turn=(a,b,t)=>a+((b-a+540)%360-180)*t;
export function createHenLadderJourney(worker,event,frame,heading,walkRoute){return guardHenConstruction(worker,()=>buildHenLadderJourney(worker,event,frame,heading,walkRoute));}
function buildHenLadderJourney(worker,event,frame,heading,walkRoute){
 const wooden=event.tower.kind==='wooden-spotlight-tower',root=worker.root,entry={p:root.position.clone(),q:root.quaternion.clone()};
 const climb=createHenLadderMotion(worker,{...LADDER_PRESETS.tower,exitWidth:IRON_LADDER_EXIT.width,...(wooden?{width:WOODEN_LADDER.width,exitWidth:WOODEN_LADDER.exitWidth,railTop:WOODEN_LADDER.railTop,railThickness:.085,railDepth:.10,rungThickness:.062,rungDepth:.082,hatch:{front:WOODEN_LADDER.z+.35-1.25,back:WOODEN_LADDER.z+.35-2.25,half:.5}}:{})});
 const bones=climb.skeleton.bones,feet=climb.limbs.filter(l=>l.id.startsWith('foot')),capture=()=>({p:root.position.clone(),q:root.quaternion.clone(),bones:bones.map(b=>b.quaternion.clone()),feet:feet.map(l=>({p:l.c.localToWorld(l.offset.clone()),q:l.c.getWorldQuaternion(new T.Quaternion())}))});
 climb.apply(0,frame);const bottom=capture();climb.apply(1,frame);const top=capture();
 const anchor=(pose,upper)=>{const p=pose.p.clone();p.y=frame.origin[1]+(upper?climb.definition.height:0);return p.toArray();};
 const low=walkRoute(event,anchor(bottom,false),false),high=walkRoute(event,anchor(top,true),true);let contacts=[],disposed=false,result;const phases=[];let duration=0;
 function standing(point,yaw){climb.reset();climb.folded();climb.tail(point.y>frame.origin[1]+3?1:0);root.position.copy(point);root.quaternion.copy(yawQ(yaw));root.updateMatrixWorld(true);climb.skeleton.update();}
 function add(label,seconds,fn){phases.push({label,start:duration,end:duration+seconds,fn});duration+=seconds;}
 function handoff(pose,t,point){const w=ease(t);standing(point,frame.heading);const source=capture();bones.forEach((b,i)=>b.quaternion.copy(source.bones[i]).slerp(pose.bones[i],w));root.position.lerpVectors(source.p,pose.p,w);root.position.y-=.065*Math.sin(Math.PI*w)**2;root.quaternion.copy(source.q).slerp(pose.q,w);root.updateMatrixWorld(true);for(const[i,l]of feet.entries()){const step=ease((w-i*.5)*2),target=source.feet[i].p.clone().lerp(pose.feet[i].p,step);target.y+=.045*Math.sin(Math.PI*step)**2;const q=source.feet[i].q.clone().slerp(pose.feet[i].q,step);climb.solve(l,target,q);contacts.push({id:l.id,kind:'floor',planted:step===0||step===1,worldPoint:target.toArray(),error:l.c.localToWorld(l.offset.clone()).distanceTo(target)});}climb.skeleton.update();}
 function addWalk(label,points,startYaw,endYaw,{fixedYaw,lastFacing=false,firstFacing=false}={}){const clips=[];let clock=0,yaw=startYaw;const append=(kind,seconds,data)=>{clips.push({kind,start:clock,end:clock+seconds,...data});clock+=seconds;};const rotate=(p,target)=>{const delta=turn(yaw,target,1)-yaw,n=Math.ceil(Math.abs(delta)/70);for(let i=0;i<n;i++){append('turn',Math.max(.20,Math.abs(delta/n)/280),{a:p,b:p,from:yaw,to:yaw+delta/n});yaw+=delta/n;}};
  for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],len=a.distanceTo(b);if(len<1e-5)continue;const target=fixedYaw??(firstFacing&&i===1?startYaw:lastFacing&&i===points.length-1?endYaw:Math.atan2(b.z-a.z,b.x-a.x)*180/Math.PI);rotate(a,target);append('walk',Math.max(.35,len/1.5),{a,b,from:yaw,to:yaw,steps:Math.max(2,Math.ceil(len/.18/2)*2)});}rotate(points.at(-1),endYaw);
  add(label,clock,t=>{const c=clips.find(c=>t<=c.end)||clips.at(-1);if(!c){standing(points.at(-1),endYaw);return;}const u=ease((t-c.start)/(c.end-c.start)),yaw=turn(c.from,c.to,u),point=c.a.clone().lerp(c.b,u);standing(point,yaw);root.position.y-=.08*Math.min(ease(u/.18),ease((1-u)/.18));root.updateMatrixWorld(true);for(const[i,l]of feet.entries()){let f,q,planted;if(c.kind==='turn'){f=ease((u-i*.5)*2);q=yawQ(c.from).slerp(yawQ(c.to),f);planted=f===0||f===1;}else{const clock=u*c.steps,active=Math.min(c.steps-1,Math.floor(clock)),step=active%2===i?active:active-1,phase=active%2===i?clock-active:1,a=(step<=1?0:step-1)/c.steps,b=(step>=c.steps-2?c.steps:step+1)/c.steps;f=step<0?0:T.MathUtils.lerp(a,b,ease(phase));q=yawQ(c.from);planted=step<0||phase===0||phase===1;l.lift=step<0?0:.06*Math.sin(Math.PI*phase)**2;}
   const rest=climb.rest.get(l.c).clone().add(l.offset),target=c.kind==='turn'?rest.clone().applyQuaternion(yawQ(c.from)).add(c.a).lerp(rest.clone().applyQuaternion(yawQ(c.to)).add(c.b),f):rest.applyQuaternion(q).add(c.a.clone().lerp(c.b,f));target.y+=c.kind==='turn'?.045*Math.sin(Math.PI*f)**2:l.lift;climb.solve(l,target,q);contacts.push({id:l.id,kind:'floor',planted,worldPoint:target.toArray(),error:l.c.localToWorld(l.offset.clone()).distanceTo(target)});}climb.skeleton.update();});
 }
 const up=event.direction==='up';if(up){addWalk('Approach',low,heading,frame.heading);add('Set wing braces',.55,t=>handoff(bottom,t/.55,low.at(-1)));add('Climb',6,t=>{contacts=climb.apply(t/6,frame).contacts;});add('Settle on landing',.4,t=>handoff(top,1-t/.4,high[0]));addWalk('Walk to destination',high,frame.heading,heading,{lastFacing:true});}else{addWalk('Approach',high.slice().reverse(),heading,frame.heading,{firstFacing:true});add('Set wing braces',.4,t=>handoff(top,t/.4,high[0]));add('Climb',6,t=>{contacts=climb.apply(t/6,{...frame,direction:'down'}).contacts;});add('Settle on ground',.55,t=>handoff(bottom,1-t/.55,low.at(-1)));addWalk('Walk to destination',low.slice().reverse(),frame.heading,heading,{fixedYaw:frame.heading});}
 return{climb,definition:climb.definition,duration,phases:phases.map(({label,start,end})=>({label,start,end})),apply(progress){if(disposed)throw Error('Hen journey is disposed');if(!Number.isFinite(progress))throw Error('Invalid hen journey progress');contacts=[];const t=T.MathUtils.clamp(progress,0,1)*duration,p=phases.find(p=>t<=p.end)||phases.at(-1);p.fn(t-p.start);result={phase:p.label,time:t,duration,root:root.position.toArray(),worldRoot:root.position.toArray(),contacts,unarmed:true,airborne:contacts.some(c=>c.kind==='airborne')};return result;},diagnostics:()=>result,dispose(){if(disposed)return;climb.dispose();root.position.copy(entry.p);root.quaternion.copy(entry.q);root.updateMatrixWorld(true);disposed=true;}};
}
